import{Q as e,X as t,ft as n,n as r}from"./chunks/framework.Dc2C-di8.js";var i=JSON.parse(`{"title":"Homebrew Builds Keep Recon's Ad-Hoc Privacy Identity","description":"","frontmatter":{"id":"decision.0005","title":"Homebrew Builds Keep Recon's Ad-Hoc Privacy Identity","status":"accepted","established-by":"user.2026-10-29","supersedes":["decision.0002"]},"headers":[],"relativePath":"decisions/0005-homebrew-ad-hoc-privacy-identity.md","filePath":"decisions/0005-homebrew-ad-hoc-privacy-identity.md"}`),a={name:`decisions/0005-homebrew-ad-hoc-privacy-identity.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="homebrew-builds-keep-recon-s-ad-hoc-privacy-identity" tabindex="-1">Homebrew Builds Keep Recon&#39;s Ad-Hoc Privacy Identity <a class="header-anchor" href="#homebrew-builds-keep-recon-s-ad-hoc-privacy-identity" aria-label="Permalink to “Homebrew Builds Keep Recon&#39;s Ad-Hoc Privacy Identity”">​</a></h1><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to “Summary”">​</a></h2><p>Recon retains its executable-owned <code>me.malstrom.recon</code> privacy identity. Homebrew source and bottle builds remain ad-hoc signed, so users grant Accessibility and Screen Recording to each installed build; local Developer ID signing remains optional for preserving grants across in-place development rebuilds.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>Decision 0002 established that privacy grants belong to Recon rather than its launcher, and deferred CI signing until a distribution channel existed. Homebrew now supplies that channel, but its formula and bottle builds do not have Mark&#39;s Developer ID private key. Putting that credential into the personal tap&#39;s CI would broaden access to a signing identity for every formula build, while a Developer-ID-signed prebuilt archive would bypass the requested plain source-formula and bottle workflow. Recon still needs a stable bundle identifier, observable permission state, and an explicit account of when grants survive replacement.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Recon&#39;s privacy identifier remains <code>me.malstrom.recon</code>. The bare executable embeds that <code>CFBundleIdentifier</code> and the name <code>recon</code> in its <code>__TEXT,__info_plist</code> section. Commands whose behavior or report depends on Recon&#39;s own grants re-execute once with the private responsibility-disclaim spawn attribute. They never use the launcher&#39;s grants as a fallback. Permission requests and typed failures retain decision 0002&#39;s behavior; <code>recon context</code> reports identity, signing, and preflight permission state without requesting a grant.</p><p>Homebrew builds and bottles use the ad-hoc signatures produced by the build. The formula does not request a Developer ID credential, notarize a separate archive, or alter TCC state. Users grant Screen Recording and Accessibility to the installed <code>recon</code> executable and repeat the grants when an upgrade or reinstall changes its ad-hoc code hash or versioned Cellar path. <code>recon context</code> is the non-interactive way to inspect the current installation&#39;s grants and signing facts.</p><p>A developer may still sign a stable local executable with a Developer ID Application identity and the identifier <code>me.malstrom.recon</code>, using <code>RECON_SIGNING_IDENTITY=… mise run recon:sign</code>, to preserve grants across in-place rebuilds at that path. This optional development arrangement is not a requirement for Homebrew installation.</p><h2 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to “Rationale”">​</a></h2><p>The existing privacy model depends on a consistent executable identity, not on a particular signing certificate. Ad-hoc Homebrew builds preserve that model and the requested bottle supply chain without distributing a private key or maintaining a second binary artifact. Making re-granting explicit avoids presenting an ad-hoc bottle as though it had the upgrade continuity of a Developer-ID-signed installation.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives considered”">​</a></h2><ul><li>Store a Developer ID private key in tap CI — grants a repository-wide release workflow access to a long-lived signing credential solely to preserve local privacy grants.</li><li>Publish a separately signed and optionally notarized binary archive — preserves grants more effectively but replaces the requested source-built formula and CI bottle path with a second release system.</li><li>Keep requiring every user to sign Recon locally with Developer ID — excludes users without a paid signing identity and makes the canonical installation harder without improving observation behavior.</li><li>Return privacy grants to the launching terminal — avoids Recon-owned signing concerns but makes results depend on the launcher, which decision 0002 rejected.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><h3 id="good" tabindex="-1">Good <a class="header-anchor" href="#good" aria-label="Permalink to “Good”">​</a></h3><ul><li>Homebrew installation needs no signing certificate or new credential in CI.</li><li>Recon keeps the same bundle identifier, responsible-process behavior, permission errors, and read-only <code>context</code> report across installation methods.</li><li>The formula and bottles exercise the same native artifacts users receive.</li><li>Developers who need stable grants across repeated local builds retain the existing Developer ID signing task.</li></ul><h3 id="bad" tabindex="-1">Bad <a class="header-anchor" href="#bad" aria-label="Permalink to “Bad”">​</a></h3><ul><li>Homebrew upgrades and replaced bottles can require fresh Accessibility and Screen Recording grants.</li><li>Moving between a Homebrew installation and a development copy creates separate privacy clients and grant state.</li><li>Recon continues to depend on private responsibility-disclaim and code-signing-query interfaces.</li><li>macOS 15 and later can still periodically request Screen Recording reconfirmation independently of Recon&#39;s release mechanism.</li></ul><h2 id="revision-history" tabindex="-1">Revision history <a class="header-anchor" href="#revision-history" aria-label="Permalink to “Revision history”">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>Change</th><th>Authority</th></tr></thead><tbody><tr><td>2026-10-29</td><td>Preserved Recon&#39;s privacy identity while accepting ad-hoc Homebrew builds and their re-granting cost.</td><td>user.2026-10-29</td></tr></tbody></table>`,20)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};